namespace GeetaStudio.Api;

public static class FactoryPage
{
    public const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Evergreen plans and review drafts</title>
<style>body{font:17px system-ui;max-width:1150px;margin:2rem auto;padding:1rem;color:#234}section,article,fieldset{border:1px solid #ccd;padding:1rem;margin:1rem 0}label{display:block;margin:.5rem 0}input,select,textarea,button{font:inherit;padding:.4rem;max-width:95%}textarea{width:95%;min-height:5rem}pre{white-space:pre-wrap}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccd;padding:.4rem}button{margin:.3rem}</style>
<h1>Evergreen journeys and draft factory</h1><p>Plan from reviewed lessons, reuse a compatible cast and create six linked review drafts. Inventory is not publication or demonstrated demand. Local templates are deterministic fixtures with no paid generation. AI mode pins a qualified route and a workflow; paid usage and unresolved reservations remain visible. Every output requires editorial evaluation and approval.</p>
<p><a href="/staff/workflows">Inspect workflows and original usage</a> · <a href="/staff/editorial">Editorial review</a> · <a href="/staff/lessons">Review source lessons</a> · <a href="/staff/characters">Manage characters and casting</a></p>
<label>Tenant <select id="tenant"></select></label><label>Universe <select id="universe"></select></label><button id="load">Refresh inventory</button><p id="status" role="status" aria-live="polite"></p>
<section><h2>Propose two pilot journeys</h2><label>Reviewed lessons (select one to three) <select id="lessons" multiple></select></label><label>Pilot key <input id="pilotKey" value="pilot"></label>
<label>Approved bible <select id="bible"></select></label><label>Episode <select id="episode"></select></label><label>Situation tags <input id="situations" value="collaboration"></label><label>Required skills <input id="skills"></label><label>Roles <input id="roles" value="Lead"></label><label>Continuity tags <input id="continuity" value="original-timeline"></label>
<label>Pinned character (optional) <select id="pin"></select></label><label>Pinned role <input id="pinRole" value="Lead"></label><label>Approved relationships <select id="relationships" multiple></select></label><button id="castPreview">Check cast</button><div id="castReasons"></div>
<button id="pilots">Propose chronological and practical journeys</button><p>Proposals remain Draft until actual editorial review. Missing cast/rights/meaning reviews block generation; a familiar name is not evidence.</p></section>
<section><h2>Plans and explicit revisions</h2><div id="plans"></div><label>Plan to edit <select id="editPlan"></select></label><label>New title <input id="title"></label><label>Generation mode <select id="adapter"><option value="local-template.a.v1">Deterministic local template A</option><option value="local-template.b.v1">Deterministic local template B</option><option>ai-workflow.v1</option></select></label><label>Configured workflow with qualified route <select id="workflow"></select></label><div id="directions"></div><button id="save">Save next plan revision</button></section>
<section><h2>Estimate and start a bounded batch</h2><label>Approved plan <select id="plan"></select></label><button id="estimate">Show effort and limits</button><div id="estimateResult"></div>
<label>Business request key <input id="business" value="pilot-run-1"></label><label>Maximum generated characters <input id="chars" type="number" value="96000"></label><label>Maximum generation cost <input id="cost" type="number" value="0"></label><label>Currency <input id="currency" value="INR"></label><label>Original deadline seconds <input id="deadline" type="number" value="300"></label><label>Maximum draft items <input id="items" type="number" value="60"></label><button id="start">Queue review drafts</button><p>Same business key and exact inputs reuse the existing batch. Pause/resume preserves its deadline and accepted output. New inputs need an explicit plan version and business key.</p><div id="batches"></div></section>
<section><h2>Coverage and duplicate outcomes</h2><p>Generated and reviewed counts are separate. Published counts represent recorded publications, never draft inventory. Rights-withheld output remains blocked. Token overlap is a conservative duplicate proxy; no neural semantics or demand forecast is claimed.</p><div id="coverage"></div></section>
<section><h2>Linked review drafts</h2><div id="artifacts"></div></section>
<script>
const $=id=>document.getElementById(id),op=()=>crypto.randomUUID(),parts=id=>$(id).value.split(',').map(x=>x.trim()).filter(Boolean);
let lessons=[],plans=[],characters=[],relationships=[],episodes=[],edit=null;
const base=()=>'/api/v1/factory/tenants/'+$('tenant').value+'/universes/'+$('universe').value;
const registry=()=>'/api/v1/registry/tenants/'+$('tenant').value+'/universes/'+$('universe').value;
async function call(path,data){const r=await fetch(path,{credentials:'same-origin',method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-ContentOS-Staff':'1'},body:data===undefined?undefined:JSON.stringify(data)});const text=await r.text();const value=text?JSON.parse(text):null;if(!r.ok)throw Error(value?.error||'Request failed');return value;}
async function act(fn){try{$('status').textContent='Working…';await fn();$('status').textContent='Done.';}catch(e){$('status').textContent=e.message;}}
function select(id,rows,label,empty=false){const el=$(id),old=el.value;el.replaceChildren();if(empty){const o=document.createElement('option');o.value='';o.textContent=id==='workflow'?'Choose a configured workflow':'Automatic compatible cast';el.append(o);}for(const row of rows){const o=document.createElement('option');o.value=row.id;o.textContent=label(row);el.append(o);}if(rows.some(x=>x.id===old))el.value=old;}
function para(el,label,value){const p=document.createElement('p'),s=document.createElement('strong');s.textContent=label+': ';p.append(s,document.createTextNode(String(value??'—')));el.append(p);}
function review(kind,row){const button=document.createElement('button');button.textContent='Record editorial review';button.onclick=()=>act(async()=>{const evidence=prompt('manual: actual review reference, or fixture: test-only reference');if(!evidence)return;await call(base()+'/'+kind+'/'+row.id+'/review',{operationId:op(),expectedRowVersion:row.rowVersion,approve:confirm('Approve? Cancel records rejection.'),evidenceReference:evidence});await load();});return button;}
function brief(){const id=$('lessons').selectedOptions[0]?.value,lesson=lessons.find(l=>l.id===id);if(!lesson)throw Error('Choose a reviewed lesson.');return{bibleRevisionId:$('bible').value,episodeId:$('episode').value,audienceId:lesson.snapshot.audience.rules.audience.audienceId,locale:lesson.snapshot.locale.rules.locale.locale,situationTags:parts('situations'),skillTags:parts('skills'),learningObjectives:lesson.sections.learningGoals,roles:parts('roles'),continuityTags:parts('continuity'),subjectTags:[],budget:{maxSpeakingCharacters:4,maxEstimatedCost:0,currency:$('currency').value,requireMedia:false},pinnedChoices:$('pin').value?[{characterId:$('pin').value,role:$('pinRole').value,presentationRevisionId:null}]:[],mode:'Draft'};}
function field(group,obj,key,label,numeric=false){const wrap=document.createElement('label');wrap.textContent=label+' ';const input=document.createElement('input');input.type=numeric?'number':'text';input.value=obj[key];input.onchange=()=>obj[key]=numeric?Number(input.value):input.value;wrap.append(input);group.append(wrap);}
function editPlan(){const p=plans.find(x=>x.id===$('editPlan').value);edit=p?.snapshot?structuredClone(p.snapshot.rules):null;$('directions').replaceChildren();if(!edit)return;$('title').value=edit.title;$('adapter').value=edit.adapter;$('workflow').value=edit.workflowDefinitionId||'';
for(const b of edit.briefs){const group=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=b.key+' / '+b.chapter+'.'+b.verse+' / '+b.journey+' #'+b.position;group.append(legend);field(group,b,'priority','Editorial priority',true);field(group,b,'journey','Journey');field(group,b,'position','Journey position',true);for(const f of b.formats){const label=document.createElement('label');label.textContent=f.kind+' editorial direction ';const input=document.createElement('textarea');input.value=f.instruction;input.onchange=()=>f.instruction=input.value;label.append(input);group.append(label);}$('directions').append(group);}}
async function load(){
const lessonBase='/api/v1/lessons/tenants/'+$('tenant').value+'/universes/'+$('universe').value;
const data=await Promise.all([call(base()+'/plans'),call(lessonBase+'/variants'),call(registry()+'/bibles'),call(registry()+'/characters'),call(registry()+'/episodes'),call(registry()+'/relationships'),call(base()+'/batches'),call(base()+'/artifacts'),call(base()+'/coverage')]);
select('workflow',await call(base()+'/generation-workflows'),d=>d.settings.key+' v'+d.settings.version+' / route '+d.settings.routeId,true);plans=data[0];lessons=data[1].filter(l=>l.reviewStatus==='Approved'&&!l.outputWithheld);characters=data[3];episodes=data[4];relationships=data[5];
select('lessons',lessons,l=>l.snapshot.bundle.locator+' / '+l.snapshot.audience.rules.key+' / '+l.snapshot.locale.rules.locale.locale);
select('bible',data[2].filter(b=>b.reviewStatus==='Approved'),b=>b.rules.title+' v'+b.version);select('episode',episodes,e=>e.key);select('pin',characters.map(c=>({id:c.characterId,c})),x=>x.c.profile.rules.name+' / '+x.c.status,true);
select('relationships',relationships.filter(x=>x.reviewStatus==='Approved'),x=>x.key+' v'+x.version);
select('editPlan',plans.filter(p=>!p.outputWithheld),p=>p.snapshot.rules.title+' v'+p.snapshot.rules.version);select('plan',plans.filter(p=>p.reviewStatus==='Approved'&&!p.outputWithheld),p=>p.snapshot.rules.title+' v'+p.snapshot.rules.version);
$('plans').replaceChildren();for(const p of plans){const a=document.createElement('article');para(a,'Plan',p.snapshot?p.snapshot.rules.title+' v'+p.snapshot.rules.version:'Rights-withheld plan');para(a,'Review',p.reviewStatus+' / '+(p.reviewEvidence||'Pending'));if(p.snapshot)for(const b of p.snapshot.briefs){para(a,'Evidence',b.brief.chapter+'.'+b.brief.verse+' / '+b.lesson.snapshot.bundle.locator);para(a,'Cast',b.cast.cast.map(c=>c.character.profile.rules.name+' ('+c.role+', profile v'+c.character.profile.version+')').join('; '));}if(p.reviewStatus==='Draft'&&!p.outputWithheld)a.append(review('plans',p));$('plans').append(a);}
$('batches').replaceChildren();for(const b of data[6]){const a=document.createElement('article');para(a,b.businessKey,b.state+' / '+b.outcome);para(a,'Usage',b.generatedCharacters+' characters / generation cost '+b.generationCost+' '+b.budget.currency+'; outstanding reservation '+b.generationReserved+'; worst-case allocation '+b.estimatedGenerationCost);for(const w of b.work)para(a,w.briefKey+' / '+w.format,w.state+' / '+w.outcome+' / workflow '+(w.workflowId||'none')+' '+(w.workflowState||''));for(const action of ['Pause','Resume','Cancel']){const button=document.createElement('button');button.textContent=action;button.onclick=()=>act(async()=>{await call(base()+'/batches/'+b.id+'/control',{operationId:op(),expectedRowVersion:b.rowVersion,action});await load();});a.append(button);}$('batches').append(a);}
$('coverage').replaceChildren();const table=document.createElement('table'),head=document.createElement('tr');for(const label of ['Verse / concept','Locale / format','Planned','Generated','Reviewed','Recorded published','Publicly usable','Reused','Duplicate rejections','Withheld','Fatigue / priority']){const cell=document.createElement('th');cell.textContent=label;head.append(cell);}table.append(head);for(const c of data[8]){const tr=document.createElement('tr');for(const value of [c.chapter+'.'+c.verse+' / '+c.concept,c.locale+' / '+c.format,c.planned,c.generated,c.reviewed,c.published,c.publiclyUsable,c.reused,c.rejectedDuplicates,c.withheld,c.topicFatigue+' / '+c.suggestedPriority]){const cell=document.createElement('td');cell.textContent=value;tr.append(cell);}table.append(tr);}$('coverage').append(table);
$('artifacts').replaceChildren();for(const d of data[7]){const a=document.createElement('article');para(a,'Review',d.reviewStatus+' / '+(d.reviewEvidence||'Pending'));if(d.snapshot){if(d.snapshot.generation)para(a,'Generated fiction review',d.snapshot.generation.fictionClaimRevisionId+' / review this claim in Evidence before content approval');para(a,'Lineage',d.snapshot.briefKey+' / '+d.snapshot.format+' / '+d.snapshot.adapter+' / '+d.snapshot.input.lesson.snapshot.bundle.locator);const text=document.createElement('pre');text.textContent=d.snapshot.output.body;a.append(text);if(d.reviewStatus==='Draft')a.append(review('artifacts',d));}else para(a,'Output','Withheld: current evidence or rights unavailable.');$('artifacts').append(a);}editPlan();
}
$('load').onclick=()=>act(load);$('editPlan').onchange=editPlan;
$('castPreview').onclick=()=>act(async()=>{const p=await call(registry()+'/cast',brief());$('castReasons').replaceChildren();for(const c of p.candidates)para($('castReasons'),c.character.profile.rules.name+' / '+c.role,c.reasons.join('; '));for(const role of p.missingRoles)para($('castReasons'),'Missing role',role+' — register a compatible guest in the character studio.');});
$('pilots').onclick=()=>act(async()=>{await call(base()+'/pilots',{operationId:op(),key:$('pilotKey').value,lessonVariantIds:[...$('lessons').selectedOptions].map(x=>x.value),cast:brief(),relationships:[...$('relationships').selectedOptions].map(x=>x.value)});await load();});
$('save').onclick=()=>act(async()=>{if(!edit)throw Error('Select a plan.');edit.operationId=op();edit.version=Math.max(...plans.filter(p=>p.snapshot?.rules.key===edit.key).map(p=>p.snapshot.rules.version))+1;edit.title=$('title').value;edit.adapter=$('adapter').value;edit.workflowDefinitionId=edit.adapter==='ai-workflow.v1'?$('workflow').value:null;await call(base()+'/plans',edit);await load();});
$('estimate').onclick=()=>act(async()=>{const e=await call(base()+'/plans/'+$('plan').value+'/estimate');$('estimateResult').replaceChildren();for(const [key,value] of Object.entries(e))if(key!=='planId')para($('estimateResult'),key.replace(/([A-Z])/g,' $1'),value);if(e.generationCurrency)$('currency').value=e.generationCurrency;$('cost').value=e.generationCost;$('chars').value=e.maximumCharacters;$('items').value=e.items;});
$('start').onclick=()=>act(async()=>{await call(base()+'/batches',{operationId:op(),businessKey:$('business').value,planId:$('plan').value,budget:{maxGenerationCost:Number($('cost').value),currency:$('currency').value,maxGeneratedCharacters:Number($('chars').value),deadlineSeconds:Number($('deadline').value),maxItems:Number($('items').value)}});await load();});
async function universes(){select('universe',await call('/api/v1/core/tenants/'+$('tenant').value+'/universes'),u=>u.name);}
$('tenant').onchange=()=>act(universes);act(async()=>{select('tenant',await call('/api/v1/core/tenants'),t=>t.name);await universes();});
</script></html>
""";
}
